#!/usr/bin/env python3
"""
Write src/html5_entities.js from the interpreter's own html.entities.html5 table.

The table is the one Python's html.unescape reads, so the Worker decodes the same named references the
pip scanner decodes. It is extracted, not retyped.

    python3 compile_entities.py
"""
import json
import sys
from html.entities import html5
from pathlib import Path

OUT = Path(__file__).parent / "src" / "html5_entities.js"


def main():
    lines = [
        "// AUTO-GENERATED by compile_entities.py - DO NOT EDIT",
        "// Source: Python %s html.entities.html5 (%d names, %d of them without the closing semicolon)"
        % (sys.version.split()[0], len(html5), sum(1 for k in html5 if not k.endswith(";"))),
        "// A key keeps its semicolon when the table has one: `amp;` and `amp` are two keys, as in Python.",
        "export const HTML5_ENTITIES = new Map([",
    ]
    for key in sorted(html5):
        lines.append("  [%s, %s]," % (json.dumps(key), json.dumps(html5[key])))
    lines.append("]);")
    OUT.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print("wrote", OUT, len(html5))


if __name__ == "__main__":
    main()
